 const attemptDetail=t=>!t.attempt?'':t.kind==='learn'||t.kind==='roleplay'&&t.roleplay_purpose==='learning'?' · 已完成':` · 最近得分 ${t.attempt.score} 分`;
 shell(`<div class="page-heading"><div><span class="eyebrow">${esc(state.user.region)} · 门店学习</span><h1>学习总览</h1><p>你好，${esc(state.user.name)}。这里汇总了你的学习安排、考试和对练任务。</p></div><button class="button secondary" data-jump="knowledge">浏览知识库 <span>→</span></button></div><section class="learning-hero"><div class="hero-copy"><span class="hero-kicker">门店学习工作台</span><h2>把客户反馈，<br>变成下一步行动</h2><p>从知识资料出发，完成学习、考核与话术练习。</p><div class="hero-actions"><button class="button" id="start-learning">开始学习</button><button class="button secondary" data-jump="roleplay">练习沟通话术</button></div></div><div class="hero-art" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="hero-mark">百应<br><small>学习成长</small></div></div></section><div class="stat-strip"><div><span>待完成任务</span><strong>${pending.length}</strong><small>${learn.filter(t=>!t.attempt?.passed).length} 项学习 · ${exams.filter(t=>!t.attempt?.passed).length} 场考试 · ${practice.filter(t=>!t.attempt?.passed).length} 项对练</small></div><div><span>已通过考核</span><strong>${passed.filter(t=>t.kind==='exam'||t.kind==='roleplay'&&t.roleplay_purpose==='exam').length}</strong><small>按任务通过分数统计</small></div><div><span>知识学习</span><strong>${learn.length}</strong><small>已分配的阅读资料</small></div><div><span>未读通知</span><strong>${notices.length}</strong><small>总部及区域学习安排</small></div></div><div class="home-columns"><section class="panel focus-panel"><div class="section-heading"><div><span class="eyebrow">优先完成</span><h2>我的学习任务</h2></div><span class="count-pill">${pending.length} 项待完成</span></div>${value.tasks.length?`<div class="list">${[...value.tasks].sort((a,b)=>(a.attempt?.passed?1:expired(a)?2:0)-(b.attempt?.passed?1:expired(b)?2:0)||new Date(a.due_at)-new Date(b.due_at)).map(t=>`<div class="list-item"><div class="task-icon ${t.kind==='exam'||t.kind==='roleplay'&&t.roleplay_purpose==='exam'?'exam':''}">${taskIcon(t)}</div><div class="task-copy"><div class="row"><strong>${esc(t.title)}</strong><span class="badge ${t.attempt?.passed?'':'orange'}">${attemptLabel(t)}</span></div><p>${esc(taskLabel(t))} · ${esc(t.document_title)} · 截止 ${date(t.due_at)}${attemptDetail(t)}</p></div><button class="button small" data-task="${t.id}">${t.attempt?.passed?'查看记录':expired(t)?'查看任务':t.attempt?'再次开始':'立即开始'} <span>→</span></button></div>`).join('')}</div>`:'<div class="empty">当前没有分配给你的学习、考试或对练任务。</div>'}</section><aside class="home-aside"><section class="panel notice-panel"><div class="section-heading"><div><span class="eyebrow">学习提醒</span><h2>通知</h2></div>${notices.length?`<span class="count-pill">${notices.length} 条未读</span>`:''}</div>${value.notices.length?`<div class="list">${[...value.notices].sort((a,b)=>Number(Boolean(a.read_at))-Number(Boolean(b.read_at))||b.created_at.localeCompare(a.created_at)).map(n=>`<div class="list-item ${n.read_at?'':'notice-unread'}"><div><strong>${esc(n.title)}</strong>${n.read_at?'':' <span class="badge new-task">新任务</span>'}<p>截止 ${date(n.due_at)} · ${n.read_at?'已读':'未读'}</p></div><button class="text-action" data-notice="${n.id}" data-task="${n.task_id}">查看</button></div>`).join('')}</div>`:'<div class="empty small-empty">暂无新通知</div>'}</section></aside></div>`);
 document.querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>action(async()=>{if(b.dataset.notice)await api(`/api/notifications/${b.dataset.notice}/read`,'POST');state.currentTask=b.dataset.task;state.page='task-detail';render()}));
 document.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>{state.page=b.dataset.jump;render()});
 document.querySelector('#start-learning')?.addEventListener('click',()=>action(async()=>{const docs=(await api('/api/documents')).documents;if(!docs.length){message('当前区域还没有可学习资料');return}state.currentDoc=docs[0].id;state.assistantMessages=[];state.page='knowledge';await render()}));
